mapper.select:
SELECT 
    f.*,
    c.customer_name as customerName,
    e.name as employeeName
FROM customer_follow f
LEFT JOIN customer c ON f.customer_id = c.customer_id
LEFT JOIN employee e ON f.employee_id = e.id
WHERE 1=1

    AND f.follow_type = #{params.followType}


    AND f.stage = #{params.stage}


    AND f.customer_id = #{params.customerId}


    AND f.employee_id = #{params.employeeId}


    AND f.follow_time >= #{params.startDate}


    AND f.follow_time <= #{params.endDate}


    AND c.customer_name LIKE CONCAT('%', #{params.customerName}, '%')

ORDER BY f.follow_time DESC

SELECT COUNT(*) as totalCount, COUNT(CASE WHEN DATE(follow_time) = CURDATE() THEN 1 END) as todayCount, COUNT(CASE WHEN DATE(follow_time) >= DATE_SUB(CURDATE(), INTERVAL 7 DAY) THEN 1 END) as weekCount, COUNT(CASE WHEN DATE(follow_time) >= DATE_SUB(CURDATE(), INTERVAL 30 DAY) THEN 1 END) as monthCount, COUNT(CASE WHEN next_follow_time IS NOT NULL AND next_follow_time <= NOW() THEN 1 END) as pendingCount, COUNT(DISTINCT customer_id) as customerCount FROM customer_follow WHERE 1=1
AND follow_time >= #{params.startDate}
AND follow_time <= #{params.endDate}
AND employee_id = #{params.employeeId}

SELECT f.*, c.customer_name as customerName FROM customer_follow f LEFT JOIN customer c ON f.customer_id = c.customer_id WHERE f.follow_time >= DATE_SUB(NOW(), INTERVAL 7 DAY)
AND f.employee_id = #{params.employeeId}
ORDER BY f.follow_time DESC
LIMIT #{params.limit}
